<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { Badge,Button,Card,CardContent,Dialog,DialogContent,DialogFooter,DialogHeader,DialogTitle,Input,Switch,Table,TableBody,TableCell,TableEmpty,TableHead,TableHeader,TableRow } from '@tabtab/ui'
import { Pencil,Plus,RotateCcw,Search,Trash2 } from 'lucide-vue-next'
import { systemApi,type Department,type Role,type UserListItem } from '@/api/client'
const rows=ref<UserListItem[]>([]),roles=ref<Role[]>([]),departments=ref<Department[]>([]),keyword=ref(''),status=ref(''),open=ref(false),editing=ref<string|null>(null),loading=ref(false),error=ref('')
const form=reactive({userName:'',displayName:'',email:'',phone:'',password:'',isEnabled:true,departmentId:null as string|null,roleIds:[] as string[]})
const departmentOptions=computed(()=>{const r:{id:string;name:string}[]=[];const visit=(items:Department[],level=0)=>items.forEach(x=>{r.push({id:x.id,name:`${'　'.repeat(level)}${x.name}`});visit(x.children,level+1)});visit(departments.value);return r})
const filtered=computed(()=>rows.value.filter(x=>!status.value||String(x.isEnabled)===status.value))
async function load(){loading.value=true;error.value='';try{const [u,r,d]=await Promise.all([systemApi.users(keyword.value,1,100),systemApi.roles(),systemApi.departments()]);rows.value=u.items;roles.value=r;departments.value=d}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
function show(row?:UserListItem){editing.value=row?.id??null;Object.assign(form,row?{userName:row.userName,displayName:row.displayName,email:row.email,phone:row.phone??'',password:'',isEnabled:row.isEnabled,departmentId:row.departmentId??null,roleIds:[...row.roleIds]}:{userName:'',displayName:'',email:'',phone:'',password:'',isEnabled:true,departmentId:null,roleIds:[]});open.value=true}
async function save(){try{editing.value?await systemApi.updateUser(editing.value,form):await systemApi.createUser(form);open.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}
async function remove(row:UserListItem){if(!confirm(`确定删除用户 ${row.userName}？`))return;try{await systemApi.deleteUser(row.id);await load()}catch(e){error.value=e instanceof Error?e.message:'删除失败'}}
function reset(){keyword.value='';status.value='';load()}
onMounted(load)
</script>
<template><div class="space-y-5"><div class="flex items-center justify-between"><div><h1 class="text-3xl font-bold">人员管理</h1><p class="text-muted-foreground">维护账号、所属机构、角色和启用状态</p></div><Button @click="show()"><Plus class="mr-2 h-4 w-4"/>新增人员</Button></div><Card><CardContent class="grid gap-3 pt-6 md:grid-cols-[1fr_180px_auto]"><Input v-model="keyword" placeholder="用户名、姓名或邮箱" @keyup.enter="load"/><select v-model="status" class="h-10 rounded-md border bg-background px-3"><option value="">全部状态</option><option value="true">启用</option><option value="false">停用</option></select><div class="flex gap-2"><Button @click="load"><Search class="mr-2 h-4 w-4"/>查询</Button><Button variant="outline" @click="reset"><RotateCcw class="mr-2 h-4 w-4"/>重置</Button></div></CardContent></Card><p v-if="error" class="text-sm text-destructive">{{error}}</p><Card><CardContent class="p-0"><Table><TableHeader><TableRow><TableHead>人员</TableHead><TableHead>联系方式</TableHead><TableHead>组织机构</TableHead><TableHead>角色</TableHead><TableHead>状态</TableHead><TableHead>最近登录</TableHead><TableHead class="text-right">操作</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="row in filtered" :key="row.id"><TableCell><div class="font-medium">{{row.displayName}}</div><div class="text-xs text-muted-foreground">{{row.userName}}</div></TableCell><TableCell><div>{{row.email}}</div><div class="text-xs text-muted-foreground">{{row.phone||'-'}}</div></TableCell><TableCell>{{row.departmentName||'未分配'}}</TableCell><TableCell>{{row.roles.join('、')||'-'}}</TableCell><TableCell><Badge :variant="row.isEnabled?'default':'outline'">{{row.isEnabled?'启用':'停用'}}</Badge></TableCell><TableCell>{{row.lastLoginAt?new Date(row.lastLoginAt).toLocaleString():'从未登录'}}</TableCell><TableCell class="text-right"><Button size="icon" variant="ghost" @click="show(row)"><Pencil class="h-4 w-4"/></Button><Button size="icon" variant="ghost" :disabled="row.userName==='admin'" @click="remove(row)"><Trash2 class="h-4 w-4"/></Button></TableCell></TableRow><TableEmpty v-if="!loading&&!filtered.length" :colspan="7">暂无人员数据</TableEmpty></TableBody></Table></CardContent></Card><Dialog v-model:open="open"><DialogContent class="max-w-2xl"><DialogHeader><DialogTitle>{{editing?'编辑':'新增'}}人员</DialogTitle></DialogHeader><form class="space-y-4" @submit.prevent="save"><div class="grid gap-3 sm:grid-cols-2"><Input v-model="form.userName" required :disabled="!!editing" placeholder="用户名"/><Input v-model="form.displayName" required placeholder="显示名称"/><Input v-model="form.email" required type="email" placeholder="邮箱"/><Input v-model="form.phone" placeholder="手机号"/><select v-model="form.departmentId" class="h-10 rounded-md border bg-background px-3"><option :value="null">未分配机构</option><option v-for="item in departmentOptions" :key="item.id" :value="item.id">{{item.name}}</option></select><Input v-model="form.password" :required="!editing" type="password" :placeholder="editing?'留空则不修改密码':'初始密码'"/></div><div class="flex items-center justify-between rounded-md border p-3"><span>启用账号</span><Switch v-model="form.isEnabled"/></div><div class="rounded-md border p-3"><p class="mb-2 text-sm font-medium">角色</p><div class="flex flex-wrap gap-4"><label v-for="role in roles" :key="role.id" class="flex gap-2 text-sm"><input v-model="form.roleIds" type="checkbox" :value="role.id"/>{{role.name}}</label></div></div><DialogFooter><Button type="button" variant="outline" @click="open=false">取消</Button><Button type="submit">保存</Button></DialogFooter></form></DialogContent></Dialog></div></template>
